-- Catalogo: presentazione dei profili runtime già esistenti, 18/11/2026.
-- 14 righe / 24 campi; nessuna formula, costo, danno, requisito o gate modificato.
BEGIN;
SET LOCAL lock_timeout='4s';
LOCK TABLE public.clan_techniques IN SHARE ROW EXCLUSIVE MODE;
DO $metadata$
DECLARE patches jsonb:=$data$[{"id":"1a267759-8d21-4c49-a81f-51b2d4d81db7","name":"Frusta d'acqua","before":{"portata":null,"danno_effetto":"Su un colpo pieno, la frusta può agganciare il bersaglio e trascinarlo verso chi la usa; ostacoli e terreno possono arrestare lo spostamento."},"after":{"portata":"Entro 10 metri","danno_effetto":"Danno ordinario invariato. Su colpo pieno può trascinare il bersaglio fino a 1 m verso chi usa la tecnica. La scelta di trascinare si prepara prima dell’invio. Nessun effetto su sfioramento/negazione; arresto prima di ostacoli, dislivelli o destinazioni illegali, senza danni da urto."}},{"id":"4c8e104c-86c7-430b-9700-540170149dd2","name":"Proiettile d'acqua","before":{"portata":null,"danno_effetto":"Su un colpo pieno, l'acqua appesantisce il bersaglio e ne limita il movimento nel turno successivo."},"after":{"portata":"Entro 30 metri","danno_effetto":"Danno ordinario invariato. Su colpo pieno lascia il bersaglio appesantito dall’impatto e dall’acqua: -2 m al budget di movimento del suo prossimo turno personale, minimo zero. Riduce solo il budget simulato del turno successivo, non Velocità o la scheda. Una sola applicazione: non si somma né rinnova mentre presente; scade alla fine di quel turno, anche senza movimento."}},{"id":"6d7c0804-1ba9-4e49-8697-1a550f3608b2","name":"Soffio di brace","before":{"portata":null},"after":{"portata":"Entro 10 metri"}},{"id":"b10f8ee7-43ed-4de1-8662-bfcc08ea3a07","name":"Lama di vento","before":{"portata":null,"danno_effetto":"La Parata è meno efficace contro la lama d’aria. Schivata, Sostituzione e tecniche difensive mantengono la loro normale efficacia."},"after":{"portata":"Entro 10 metri","danno_effetto":"Danno ordinario invariato. +1 alla sola possibilità di colpire quando il bersaglio sceglie Parata. Modificatore al confronto attuale, non a potenza o danno. Zero bonus contro Schivata, Sostituzione o tecniche difensive; nessuna arma tagliata automaticamente."}},{"id":"d5605069-b381-41ad-8e6a-9c24a314c58f","name":"Grande sfondamento","before":{"portata":null,"danno_effetto":"Su un colpo pieno, la folata può respingere il bersaglio lungo la direzione dell'attacco; ostacoli, dislivelli e terreno possono arrestare lo spostamento."},"after":{"portata":"Entro 30 metri","danno_effetto":"Danno ordinario invariato. Su colpo pieno può respingere il bersaglio fino a 3 m lungo la direzione dell’attacco. Scelta preparata prima dell’invio; arresto prima di ostacoli/dislivelli/destinazioni illegali. Nessun danno da collisione o altro bersaglio colpito."}},{"id":"72cbe1fb-34c8-44c7-a053-0014b4894b3e","name":"Scarica","before":{"portata":null,"durata":"Istantanea","danno_effetto":"Parata e Schivata successive possono risultare più difficili. Sostituzione e tecniche difensive conservano la loro normale efficacia e non consumano l’apertura."},"after":{"portata":"Entro 2 metri","durata":"Impatto istantaneo; apertura consumata dal primo confronto difensivo compatibile, entro la fine del prossimo turno personale del bersaglio","danno_effetto":"Danno ordinario invariato. Su contatto e colpo pieno applica -1 al primo confronto difensivo successivo compatibile del bersaglio, entro la fine del suo prossimo turno personale. Una sola carica per bersaglio; altre Scariche non sommano né rinnovano. Consumo solo quando applicabile; niente paralisi, perdita di azione o negazione di Sostituzione. Gli altri malus seguono il contratto comune."}},{"id":"29e49eb9-56d7-4d35-afae-af14bf0c8e65","name":"Lancia di fulmine","before":{"portata":null,"danno_effetto":"La Schivata è meno efficace contro la rapidità della lancia. Parata, Sostituzione e tecniche difensive mantengono la loro normale efficacia."},"after":{"portata":"Entro 30 metri","danno_effetto":"Danno ordinario invariato. +1 alla sola possibilità di colpire quando il bersaglio sceglie Schivata. Nessuna riduzione del danno e nessun bonus a potenza. Zero bonus contro Parata, Sostituzione o tecniche difensive; niente perforazione certa o propagazione."}},{"id":"fea014d1-0d71-43dd-bd60-045fbecf3184","name":"Proiettile di roccia","before":{"portata":null,"danno_effetto":"La Parata assorbe meno efficacemente la forza dell’impatto. Schivata, Sostituzione e tecniche difensive mantengono la loro normale efficacia."},"after":{"portata":"Entro 30 metri","danno_effetto":"Danno ordinario invariato. Contro Parata ignora fino a 2 punti della riduzione numerica del danno, senza portarla sotto zero. Non cambia Resistenza, esito del confronto o le altre difese. Per ora non richiede una fonte ambientale di terra o roccia. Nessuna distruzione automatica di armature, Scudi o coperture."}},{"id":"9061c022-ca82-4d2b-8102-e208fcc6c1a2","name":"Scudo di terra","before":{"danno_effetto":"Lo scudo può attenuare o arrestare un attacco, assorbendone l’urto prima di sfaldarsi. Non può essere mantenuto come muro o copertura."},"after":{"danno_effetto":"Difesa singola già ratificata: 5 chakra per utilizzo, senza requisito di fonte ambientale, confronto difensivo ordinario. Non è una tecnica offensiva e non le viene aggiunto danno. Nessuna azione principale aggiuntiva, parata garantita, mantenimento per turno o muro permanente. Preservare compatibilità e limiti della difesa ratificata."}},{"id":"f1440a58-ee95-53dc-8ed5-a53543d970ce","name":"Colpo concatenato del leone","before":{"danno_effetto":"La difesa conserva tutte le normali possibilità contro l’intera sequenza."},"after":{"danno_effetto":"La sequenza usa un solo confronto e un solo pacchetto di danno base 25. La difesa conserva tutte le normali possibilità. Nessun danno da caduta, movimento forzato o privazione della difesa."}},{"id":"f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc","name":"Spazzata della Foglia","before":{"durata":"Istantanea","danno_effetto":"La difesa può evitare o attenuare normalmente il colpo. Soltanto un impatto pieno compromette temporaneamente il movimento del bersaglio."},"after":{"durata":"Impatto istantaneo; movimento ridotto nel prossimo turno personale del bersaglio, fino alla sua fine","danno_effetto":"Un colpo pieno non negato riduce di 2 metri il movimento disponibile nel prossimo turno personale del bersaglio, con minimo zero. Non modifica Velocità o il movimento già effettuato. Non si somma né rinnova mentre presente e scade alla fine di quel turno. Nessun effetto su sfioramento o colpo negato."}},{"id":"65719592-7de9-5aa1-8d59-e8da2338d45b","name":"Turbine della Foglia","before":{"danno_effetto":"La Parata è meno efficace contro il rapido cambio d’altezza dei due calci. Schivata, Sostituzione e tecniche difensive mantengono la loro normale efficacia."},"after":{"danno_effetto":"Contro Parata aggiunge +1 alla sola possibilità di colpire, senza aumentare il margine numerico del danno. Nessun bonus contro Schivata, Sostituzione o tecniche difensive."}},{"id":"96927a19-9908-59da-9f17-2611e031bd8d","name":"Calcio ascendente della Foglia","before":{"durata":"Istantanea","danno_effetto":"Un colpo pieno può rendere più difficile la prima Parata o Schivata successiva. Sostituzione e tecniche difensive restano pienamente efficaci e non consumano l’apertura."},"after":{"durata":"Impatto istantaneo; apertura consumata dalla prima Parata o Schivata compatibile, entro la fine del prossimo turno personale del bersaglio","danno_effetto":"Un colpo pieno non negato applica -1 al primo confronto difensivo successivo con Parata o Schivata, entro la fine del prossimo turno personale del bersaglio. Sostituzione e tecniche difensive restano efficaci e non consumano l’apertura. Non si somma né rinnova; non modifica mitigazione o numero di azioni."}},{"id":"9ac77d79-9894-5388-9753-70538ac5eaa3","name":"Entrata dinamica","before":{"danno_effetto":"Dopo una rincorsa valida, Parata e Schivata sono meno efficaci contro l’impeto del calcio. Sostituzione e tecniche difensive mantengono la loro normale efficacia."},"after":{"danno_effetto":"Richiede almeno 5 metri di rincorsa rettilinea, continua e legale verso il bersaglio, usando il movimento ordinario residuo e terminando entro 2 metri; non parte già a contatto o sotto immobilizzazione. Dopo una rincorsa valida aggiunge +1 alla sola possibilità di colpire contro Parata o Schivata, senza aumentare il margine del danno. Sostituzione e tecniche difensive restano efficaci. Nessun movimento gratuito, ripiego in un colpo semplice o inseguimento automatico."}}]$data$::jsonb;p jsonb;r jsonb;expected jsonb;before_rows jsonb;expected_rows jsonb;affected integer;
BEGIN
 IF (SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY id)) FROM public.clan_techniques t)
 IS DISTINCT FROM '3137b892d25c4d4b20177dbee5529829d7cde7a31db3bc0d3f5ea220867899b0' THEN RAISE EXCEPTION 'CATALOG_METADATA_BASELINE_DRIFT';END IF;
 IF (SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY id)) FROM public.jutsu t)
 IS DISTINCT FROM 'ac80f965af32d580f44ba8c0d2dfcd9dad44d3a6f56b903462c76137fe172e25' THEN RAISE EXCEPTION 'CATALOG_METADATA_JUTSU_DRIFT';END IF;
 IF md5(pg_get_functiondef('combat_v2_elemental_internal.technique_profile_v1(uuid)'::regprocedure))<>'331b1e75169352488965eaf4d98d1126'
 OR md5(pg_get_functiondef('combat_v2_taijutsu_internal.technique_profile_v1(uuid)'::regprocedure))<>'34d8934bb52817d648ea16bff8e8c044' THEN RAISE EXCEPTION 'CATALOG_METADATA_PROFILE_DRIFT';END IF;
 IF EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE state='in_corso') THEN RAISE EXCEPTION 'CATALOG_METADATA_COMBAT_OPEN';END IF;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO before_rows FROM public.clan_techniques t;
 FOR p IN SELECT value FROM jsonb_array_elements(patches) LOOP
  IF jsonb_typeof(p->'after')<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p->'after') k WHERE k NOT IN('portata','durata','danno_effetto')) THEN RAISE EXCEPTION 'CATALOG_METADATA_KEYS';END IF;
  SELECT to_jsonb(t) INTO STRICT r FROM public.clan_techniques t WHERE id=(p->>'id')::uuid AND is_active FOR UPDATE;
  IF (SELECT jsonb_object_agg(k,r->k) FROM jsonb_object_keys(p->'before') k) IS DISTINCT FROM p->'before' THEN RAISE EXCEPTION 'CATALOG_METADATA_ROW_DRIFT:%',p->>'id';END IF;
  expected:=r||(p->'after');
  UPDATE public.clan_techniques SET portata=expected->>'portata',durata=expected->>'durata',danno_effetto=expected->>'danno_effetto' WHERE id=(p->>'id')::uuid AND is_active;
  GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'CATALOG_METADATA_COUNT';END IF;
  IF (SELECT to_jsonb(t) FROM public.clan_techniques t WHERE id=(p->>'id')::uuid) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'CATALOG_METADATA_UNEXPECTED_DELTA';END IF;
 END LOOP;
 SELECT jsonb_agg(r.value||coalesce(p.value->'after','{}') ORDER BY r.value->>'id') INTO expected_rows
 FROM jsonb_array_elements(before_rows) r LEFT JOIN LATERAL(SELECT value FROM jsonb_array_elements(patches) WHERE value->>'id'=r.value->>'id') p ON true;
 IF (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM public.clan_techniques t) IS DISTINCT FROM expected_rows
 OR public.combat_v2_sha256(expected_rows)<>'2ee367eada52a19ed25c3653acfa67ea2a90c8bc89012d418410d94c34a5e1ce' THEN RAISE EXCEPTION 'CATALOG_METADATA_CUSTODY';END IF;
END $metadata$;
COMMIT;
